const records=[
{id:'after-rain',title:'After the rain',artist:'Morrow',genre:'Ambient',year:'2026',catalog:'PRT 001',price:8,art:'after-rain.webp',description:'Piano, tape and the space between. A slow unfolding for the hours when the world gets quiet.',story:'A fictional record made for this listening room. Six short original sound studies explore soft keys, suspended chords and a little space to breathe. Choose a side and stay a while.',tracks:[['First light','The space between','After the rain'],['Still here','Slow return','Morning, again']]},
{id:'soft-architecture',title:'Soft architecture',artist:'Form & Field',genre:'Alternative',year:'2026',catalog:'PRT 002',price:10,art:'soft-architecture.webp',description:'Angular rhythms. Softer edges. A study in repetition, movement and finding a different way through.',story:'A fictional release exploring the musical shape of a room. Short original electronic studies move from measured pulses into open harmonies. The sequence is part of the record.',tracks:[['Foundation','Open rooms','Soft architecture'],['The stairwell','A different angle','Outside']]},
{id:'blue-hours',title:'Blue hours',artist:'Low Tide',genre:'Electronic',year:'2026',catalog:'PRT 003',price:9,art:'blue-hours.webp',description:'Low frequencies and open water. Six little transmissions from the edge of the day.',story:'An imagined coastal night, told in six original sound studies. Warm electronic tones drift over slow pulses. This is a demo catalogue, created to explore how Porto could feel.',tracks:[['Last light','Undercurrent','Blue hours'],['Night swimming','Out to sea','Daybreak']]}
];
const $=s=>document.querySelector(s),audio=$('#audio'),main=$('#main');
let saved=[],owned=[];try{saved=JSON.parse(localStorage.getItem('porto-saved')||'[]');owned=JSON.parse(localStorage.getItem('porto-owned')||'[]');if(!Array.isArray(saved))saved=[];if(!Array.isArray(owned))owned=[]}catch{}
let current=records[0],side=0,track=0,playing=false,selectedSide=0,filter='All',query='',shelfFilter='All records',toastTimer;
const isWire=new URLSearchParams(location.search).has('wireframe');if(isWire){document.body.classList.add('wireframe-mode');$('.demo-pill').textContent='Interactive wireframe'}
const fmt=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
const sideName=n=>n===0?'A':'B';const asset=r=>'assets/'+r.art;const isOwned=r=>owned.includes(r.id);
function persist(){try{localStorage.setItem('porto-saved',JSON.stringify(saved));localStorage.setItem('porto-owned',JSON.stringify(owned))}catch{toast('Your browser cannot save this demo shelf. It will last for this session.')}$('#shelf-count').textContent=new Set([...saved,...owned]).size}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function getRecord(id){return records.find(r=>r.id===id)||records[0]}
function card(r,i){return `<a class="record-card" href="#record/${r.id}" aria-label="Open ${r.title} by ${r.artist}"><div class="art"><img src="${asset(r)}" alt="${r.title} record artwork" loading="lazy"><span class="card-arrow" aria-hidden="true">↗</span></div><div class="card-info"><div><h3>${r.title}</h3><p>${r.artist} <span aria-hidden="true">·</span> ${r.genre}</p></div><span class="card-number">${isOwned(r)?'OWNED':String(i+1).padStart(2,'0')}</span></div></a>`}
function saveButton(r){return `<button class="save-btn ${saved.includes(r.id)?'saved':''}" data-action="save" data-id="${r.id}" aria-label="${saved.includes(r.id)?'Remove from':'Save to'} shelf" aria-pressed="${saved.includes(r.id)}">${saved.includes(r.id)?'✓':'+'}</button>`}
function discover(){return `<div class="section-head"><div><p class="eyebrow red">A RECORD AT A TIME</p><h1>Pull something off the shelf.</h1></div><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Find a record or artist" aria-label="Find a record or artist" value=""></label></div><section class="feature" aria-label="Featured record"><a href="#record/after-rain" class="cover-wrap"><img src="assets/after-rain.webp" alt="A solitary cypress against an ivory sky and red earth"></a><div class="feature-copy"><p class="eyebrow red">ON THE TURNTABLE / 001</p><h2>After the rain</h2><p class="artist">Morrow</p><p class="feature-description">Piano, tape and the space between.<br>A record for taking your time.</p><div class="record-meta"><span>AMBIENT</span><span>2026</span><span>2 SIDES / 6 SOUND STUDIES</span></div><div class="actions"><button class="primary" data-action="play-record" data-id="after-rain" data-side="0"><span aria-hidden="true">▶</span> Drop the needle</button>${saveButton(records[0])}<a class="secondary" href="#record/after-rain">View record ↗</a></div><p class="feature-note">START AT SIDE A. LET THE RECORD UNFOLD.</p></div></section><div class="catalog-heading"><h2>Find your next listen</h2><div class="filters" aria-label="Filter by genre">${['All','Ambient','Alternative','Electronic'].map(v=>`<button class="filter ${v===filter?'active':''}" data-action="filter" data-filter="${v}" aria-pressed="${v===filter}">${v}</button>`).join('')}</div></div><div id="catalog" class="record-grid">${filteredRecords().map(card).join('')}</div><p class="legal-note">Original demo artwork and 24-second sound studies. All artists and releases in this catalogue are fictional.</p>`}
function filteredRecords(){return records.filter(r=>(filter==='All'||r.genre===filter)&&(`${r.title} ${r.artist}`.toLowerCase().includes(query.toLowerCase())))}
function tracks(r,s){return `<ol class="track-list">${r.tracks[s].map((t,i)=>`<li class="track-row ${current.id===r.id&&side===s&&track===i?'current':''}"><span class="num">${i+1}</span><button data-action="track" data-id="${r.id}" data-side="${s}" data-track="${i}" ${!isOwned(r)?'disabled':''}>${t}</button><time>0:24</time></li>`).join('')}</ol>`}
function detail(r){return `<div class="detail-top"><a href="#discover" class="back">← Back to the shelf</a><span class="eyebrow">${r.catalog} / ${r.year}</span></div><div class="detail-layout"><div><div class="detail-art"><img src="${asset(r)}" alt="${r.title} record artwork"></div><div class="sleeve-caption"><span>${r.artist.toUpperCase()}</span><span>6 ORIGINAL SOUND STUDIES</span></div></div><div class="detail-content"><p class="eyebrow red">${r.genre.toUpperCase()} / ${isOwned(r)?'DEMO OWNED COPY':'THE WHOLE RECORD'}</p><h1>${r.title}</h1><p class="artist">${r.artist}</p><div class="side-tabs" role="group" aria-label="Choose record side">${[0,1].map(s=>`<button data-action="side" data-side="${s}" class="${selectedSide===s?'active':''}" aria-pressed="${selectedSide===s}">Side ${sideName(s)}</button>`).join('')}</div>${tracks(r,selectedSide)}<div class="actions"><button class="primary coral" data-action="play-record" data-id="${r.id}" data-side="${selectedSide}">▶ Play side ${sideName(selectedSide)}</button>${saveButton(r)}<span class="muted" style="font:11px var(--mono)">1:12 / THREE TRACKS</span></div><p class="listener-note">${isOwned(r)?'Your demo copy has full track navigation and seeking.':'The record plays in order. Pause, or lift the needle to start again.'}</p><section class="ownership"><div><h3>${isOwned(r)?'A place on your shelf.':'Keep this one.'}</h3><p>${isOwned(r)?'Your demo copy includes the original audio files.':'An offline copy. Full navigation. A direct sale alongside streaming.'}</p></div>${isOwned(r)?`<a class="secondary" href="assets/${r.id}-demo.zip" download>Download demo ↓</a>`:`<button class="secondary" data-action="purchase" data-id="${r.id}">Own the record · £${r.price}</button>`}</section><p class="legal-note">${isOwned(r)?'Demo ownership only. No charge or licence has been issued.':'Illustrative price. Purchase demonstration only. No payment is taken.'}</p></div></div><section class="record-story"><h3>Behind the record</h3><p>${r.story}</p></section>`}
function shelf(){let list=records.filter(r=>(saved.includes(r.id)||isOwned(r))&&(shelfFilter!=='Owned copies'||isOwned(r))&&(shelfFilter!=='Saved records'||saved.includes(r.id)));return `<div class="section-head"><div><p class="eyebrow red">A PLACE FOR YOUR RECORDS</p><h1>Your shelf.</h1></div><span class="muted">${list.length} ${list.length===1?'record':'records'}</span></div><div class="shelf-tabs">${['All records','Saved records','Owned copies'].map(v=>`<button class="filter ${v===shelfFilter?'active':''}" data-action="shelf-filter" data-filter="${v}" aria-pressed="${v===shelfFilter}">${v}</button>`).join('')}</div>${list.length?`<div class="record-grid">${list.map(card).join('')}</div>`:`<div class="empty"><h2>A good record stays with you.</h2><p>Save something you love, or try owning a demo copy.</p><a class="primary" href="#discover">Explore the records ↗</a></div>`}<p class="legal-note">Your demo shelf is saved in this browser.</p>`}
function listening(){return `<div class="detail-top"><a class="back" href="#record/${current.id}">← Back to the record</a><span class="eyebrow red">SIDE ${sideName(side)} / ${isOwned(current)?'OWNED COPY':'CONTINUOUS LISTENING'}</span></div><div class="listening-layout"><div class="listening-art"><img src="${asset(current)}" alt="${current.title} record artwork"></div><div class="listening-info"><p class="eyebrow red" id="listening-state">${playing?'NOW PLAYING':'TAKE YOUR TIME'}</p><h1 id="listening-title">${current.tracks[side][track]}</h1><p class="artist">${current.artist}</p><p class="muted" style="font-size:13px;margin-top:8px">${current.title} · ${current.year}</p><div class="session-bars" aria-hidden="true">${Array.from({length:42},(_,i)=>`<i style="height:${8+(i*17%21)}px;animation-delay:${i*.037}s"></i>`).join('')}</div>${tracks(current,side)}<div class="actions"><button class="primary" data-action="toggle" id="focus-play">${playing?'Ⅱ Pause':'▶ Drop the needle'}</button><button class="secondary" data-action="lift">↥ Lift needle</button></div>${isOwned(current)?`<label class="listener-note" for="seek">Navigate your demo copy</label><input class="seek" id="seek" aria-label="Seek within current track" type="range" min="0" max="24" step=".1" value="${audio.currentTime}">`:`<p class="listener-note">No shuffle. No scrubbing. Just the record,<br>in the order it was made.</p>`}<button class="text-button" data-action="flip" style="margin-top:15px;font-size:13px">Turn over to side ${sideName(1-side)} ↗</button></div></div>`}
function support(){return `<div class="section-head"><div><p class="eyebrow red">FOLLOW THE MUSIC</p><h1>Your listening.<br>Your contribution.</h1></div><span class="demo-pill">MODEL EXPLAINER</span></div><p class="support-intro">Porto’s proposed subscription model follows what you listen to. Your listening time determines how your allocation is shared between the works you play.</p><div class="allocation" role="img" aria-label="70 percent rights holders, 25 percent network operators, 5 percent protocol treasury"><span></span><span></span><span></span></div><div class="allocation-grid"><article><strong>70%</strong><h3>Rights holders</h3><p>Divided among artists, labels and publishers according to registered rights.</p></article><article><strong style="color:#a994ce">25%</strong><h3>Network operators</h3><p>For running the infrastructure that serves the music.</p></article><article><strong style="color:#81afd2">5%</strong><h3>Protocol treasury</h3><p>Allocated to the Porto protocol treasury.</p></article></div><div class="info-card"><p class="eyebrow red" style="margin:0">ACCRUAL IS NOT SETTLEMENT</p><h3 style="margin-top:10px">Listening first. Settlement at the epoch boundary.</h3><p>Valid listening accrues through the period. The Beta specification uses daily settlement. The 70% rights-holder pool is divided by each work’s rights splits, so it is not a guaranteed individual artist payout.</p></div><p class="legal-note">This prototype does not attest streams, accrue money or connect to Porto’s network. The allocation explains the subscription model, not record sale fees. Source: Porto whitepaper and PIP-5. Purchase licensing, fees and settlement remain to be defined.</p>`}
function render(){const route=location.hash.slice(1)||'discover';const view=route.split('/')[0];$('#view-title').textContent={discover:'Discover',shelf:'My shelf',record:'The record',listening:'Listening',support:'Your support'}[view]||'Discover';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view||(view==='record'&&a.dataset.nav==='discover')));main.innerHTML=view==='record'?detail(getRecord(route.split('/')[1])):view==='shelf'?shelf():view==='listening'?listening():view==='support'?support():discover();if($('#search'))$('#search').value=query;persist();updatePlayer();}
function source(){audio.src=`assets/${current.id}-${sideName(side).toLowerCase()}-${track+1}.wav`;audio.load()}
async function resume(){try{await audio.play();playing=true;updatePlayer()}catch{playing=false;toast('Audio could not start. Press play to try again.');updatePlayer()}}
function pause(){audio.pause();playing=false;updatePlayer()}
async function toggle(){if(playing)pause();else{if(audio.ended){track=0;source()}if(!audio.getAttribute('src'))source();await resume()}}
function lift(){pause();track=0;source();updatePlayer();if(location.hash==='#listening')render();toast('Needle lifted. This side is back at the beginning.')}
function playRecord(id,s){const r=getRecord(id);if(r.id!==current.id||s!==side){pause();current=r;side=s;track=0;source()}else if(!audio.getAttribute('src'))source();resume();location.hash='listening';render()}
function updatePlayer(){document.body.classList.toggle('playing',playing);$('#mini-cover').src=asset(current);$('#mini-title').textContent=current.tracks[side][track];$('#mini-artist').textContent=`${current.artist} · Side ${sideName(side)}`;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause playback':`Play side ${sideName(side)}`);$('#track-caption').textContent=playing?`Track ${track+1} of 3`:audio.ended?'Side complete':audio.currentTime>0?'Paused':'Needle lifted';$('#player-mode').textContent=`SIDE ${sideName(side)} / ${isOwned(current)?'OWNED COPY':'CONTINUOUS'}`;if($('#focus-play'))$('#focus-play').textContent=playing?'Ⅱ Pause':'▶ Drop the needle';if($('#listening-state'))$('#listening-state').textContent=playing?'NOW PLAYING':'TAKE YOUR TIME';if($('#listening-title'))$('#listening-title').textContent=current.tracks[side][track];updateTime()}
function updateTime(){const elapsed=track*24+(audio.currentTime||0);$('#elapsed').textContent=fmt(elapsed);$('#remaining').textContent=fmt(Math.max(0,72-elapsed));$('#progress-fill').style.width=Math.min(elapsed/72*100,100)+'%';$('.progress-track').setAttribute('aria-valuenow',Math.round(elapsed/72*100));if($('#seek')&&document.activeElement!==$('#seek'))$('#seek').value=audio.currentTime||0}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
function about(){modal(`<p class="eyebrow red">PORTO / CONCEPT 01</p><h2>A record-led listening room.</h2><p>Based on the pitch deck’s continuous listening and optional ownership concepts, using the Porto Design System 0.1.0-dev.1.</p><ul><li>Choose a side and listen in sequence.</li><li>Pause or lift the needle. Streaming has no scrubbing.</li><li>Try a demo purchase to unlock navigation and audio downloads.</li></ul><p>The artwork and short sound studies are original demo material. Artists, records and prices are fictional. No payments, licences, stream attestations or payouts are created.</p><a class="primary" href="wireframe.html">Explore the wireframes ↗</a><button class="text-button" data-action="reset" style="margin-top:24px">Reset my demo shelf and purchases</button>`)}
function purchase(id){const r=getRecord(id);modal(`<p class="eyebrow red">KEEP THE RECORD</p><h2>Some records stay.</h2><div class="purchase-record"><img src="${asset(r)}" alt=""><div><h3>${r.title}</h3><small>${r.artist}</small></div><span class="price">£${r.price}</span></div><ul><li>Full track navigation and seeking</li><li>A downloadable copy of the demo audio</li><li>A place in your owned collection</li></ul><p>Demonstration only. This illustrative price is not a sale offer. No payment details are collected and nothing is charged.</p><button class="primary coral" data-action="confirm-purchase" data-id="${id}">Add demo copy to my shelf</button><div class="legal-note">The deck proposes prices set by artists or labels. Licensing, sale fees and purchase settlement remain to be defined.</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='save'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();toast(saved.includes(id)?'Saved to your shelf.':'Removed from saved records.')}if(a==='filter'){filter=b.dataset.filter;render()}if(a==='shelf-filter'){shelfFilter=b.dataset.filter;render()}if(a==='side'){selectedSide=+b.dataset.side;render()}if(a==='play-record')playRecord(id,+b.dataset.side);if(a==='toggle')toggle();if(a==='lift')lift();if(a==='flip'){pause();side=1-side;track=0;source();render();toast(`Side ${sideName(side)} is ready. Drop the needle when you are.`)}if(a==='purchase')purchase(id);if(a==='confirm-purchase'){if(!owned.includes(id))owned.push(id);persist();$('#dialog').close();render();toast('Demo copy added. Full navigation and downloads are unlocked.')}if(a==='track'&&isOwned(getRecord(id))){pause();current=getRecord(id);side=+b.dataset.side;track=+b.dataset.track;source();resume();render()}if(a==='reset'){saved=[];owned=[];persist();$('#dialog').close();render();toast('Demo shelf and purchases reset.')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const list=filteredRecords();$('#catalog').innerHTML=list.length?list.map(card).join(''):'<div class="empty" style="grid-column:1/-1;margin:0"><h3>No records found.</h3><p>Try another title, artist or genre.</p></div>'}if(e.target.id==='seek'&&isOwned(current)){audio.currentTime=+e.target.value;updateTime()}});
$('#play').addEventListener('click',toggle);$('#lift').addEventListener('click',lift);$('#player-record').addEventListener('click',()=>{location.hash='listening'});$('#volume').addEventListener('input',e=>audio.volume=+e.target.value);$('#about-button').addEventListener('click',about);$('#profile-button').addEventListener('click',about);$('.dialog-close').addEventListener('click',()=>$('#dialog').close());$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
audio.volume=.65;audio.addEventListener('timeupdate',updateTime);audio.addEventListener('play',()=>{playing=true;updatePlayer()});audio.addEventListener('pause',()=>{playing=false;updatePlayer()});audio.addEventListener('error',()=>{playing=false;updatePlayer();toast('The demo audio could not load. Please try again.')});audio.addEventListener('ended',()=>{if(track<2){track++;source();resume();if(location.hash==='#listening'||location.hash.startsWith('#record/'))render()}else{playing=false;updatePlayer();toast(`Side ${sideName(side)} has finished. Turn the record over when you are ready.`);if(location.hash==='#listening')render()}});
window.addEventListener('hashchange',()=>{selectedSide=0;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})});document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','A','TEXTAREA'].includes(e.target.tagName)&&!$('#dialog').open){e.preventDefault();toggle()}});render();
